import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print("")
        return

    n = int(data[0].strip())
    if n == 0:
        print("")
        return

    strings = []
    for i in range(1, n + 1):
        if i < len(data):
            strings.append(data[i].strip())

    if n == 1:
        print(strings[0])
        return

    if not strings:
        print("")
        return

    first = strings[0]
    min_len = min(len(s) for s in strings)

    prefix_len = 0
    for i in range(min_len):
        char = first[i]
        if all(s[i] == char for s in strings[1:]):
            prefix_len += 1
        else:
            break

    print(first[:prefix_len])

if __name__ == "__main__":
    main()
